import{c as o,Q as t,j as e,m as l}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Harness之后,最近爆火的 Loop Engineering 是什么？怎么做？","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-09-@smithandai-733882.md","filePath":"research/tweets/2026-06-09-@smithandai-733882.md","lastUpdated":1785909234000}'),a={name:"research/tweets/2026-06-09-@smithandai-733882.md"};function i(r,p,n,s,h,d){return t(),e("div",null,[...p[0]||(p[0]=[l('<h1 id="harness之后-最近爆火的-loop-engineering-是什么-怎么做" tabindex="-1">Harness之后,最近爆火的 Loop Engineering 是什么？怎么做？ <a class="header-anchor" href="#harness之后-最近爆火的-loop-engineering-是什么-怎么做" aria-label="Permalink to &quot;Harness之后,最近爆火的 Loop Engineering 是什么？怎么做？&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/smithandai/status/2064237463338733882" target="_blank" rel="noreferrer">@smithandai</a>（Smith铜匠・十点睡觉）<br><strong>日期</strong>：2026-06-09<br><strong>類型</strong>：Twitter Article（簡體中文）<br><strong>統計</strong>：❤️ 69 · 🔁 15 · 👁 21508 · 🔖 145</p><hr><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Prompt→Context→Harness→Loop 四層演進框架；最小可用 Loop 五部件（done check/context builder/act+capture/feedback path/stop conditions）；九步改造路徑 + 六接口設計指引（中文綜合 4 份源資料含 arXiv 2606.05608）。</p><hr><h2 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h2><ol><li>AI 使用界面演進：Prompt → Context → Harness → Loop，每層解決不同問題</li><li>Loop = Harness 上一層的控制結構（觸發/分派/檢查/記錄/恢復/停止），非「自動繼續」</li><li>最小可用 Loop 五部件：done check / context builder / act+capture / feedback path / stop conditions</li><li>Skill 是 Loop 裡的資產（複利）；無 Skill 的 Loop 每輪重付認知稅</li><li>Trigger 應最後加入；先確保 is_done/state/capture/feedback/guardrail 已就位</li></ol><hr><h2 id="關鍵數據-工具-引用" tabindex="-1">關鍵數據 / 工具 / 引用 <a class="header-anchor" href="#關鍵數據-工具-引用" aria-label="Permalink to &quot;關鍵數據 / 工具 / 引用&quot;">​</a></h2><ul><li>六接口：目標/狀態/上下文/執行/結果/停止接口</li><li>九步改造路徑（從重複任務 → 完成條件 → context pack → skill → harness → checker → external state → trigger → 預算上限）</li><li>引用：arXiv 2606.05608（&quot;The End of Software Engineering&quot;）、Matt Van Horn &quot;WTF Is a Loop?&quot;、Addy Osmani &quot;Loop Engineering&quot;、Amit Shekhar &quot;How to design a loop&quot;</li></ul><hr><h2 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h2><ol><li>綜合性強但多數概念已在其他文章出現，獨創性有限</li><li>「Trigger 最後加」的建議合理，但缺乏反例說明什麼情況下可以早加</li><li>停止條件工程是亮點，但缺乏具體 token/cost 預算數字</li></ol><hr><h2 id="_5-維度評分" tabindex="-1">5 維度評分 <a class="header-anchor" href="#_5-維度評分" aria-label="Permalink to &quot;5 維度評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8</td><td>九步路徑 + 六接口定義，可直接對照執行</td></tr><tr><td>B. 創新性 (20%)</td><td>7</td><td>結構化 + 中文表達添加獨特價值</td></tr><tr><td>C. 證據品質 (20%)</td><td>7</td><td>引用 4 份資料（含 arXiv），綜合而非摘要</td></tr><tr><td>D. 技術深度 (15%)</td><td>8</td><td>六接口 + 五部件 + 停止條件工程細節到位</td></tr><tr><td>E. 泛化性 (15%)</td><td>9</td><td>適用所有 AI 工程場景</td></tr></tbody></table><p><strong>加權總分：7.75 → Rule</strong></p><hr><h2 id="整合決策" tabindex="-1">整合決策 <a class="header-anchor" href="#整合決策" aria-label="Permalink to &quot;整合決策&quot;">​</a></h2><p><strong>Rule</strong> — Prompt→Context→Harness→Loop 四層演進 + 九步改造路徑可作為 AI 工程升級通用規則</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>一周前，Peter Steinberger 在 X 上的一句话把 AI 编程圈点着了。</p><p>大意是：别再手动提示 coding agent，去设计能提示 agent 的 loop。</p><p>这句话传播很猛，讨论也很乱。一部分人立刻喊 prompt engineering 结束了，另一部分人在问一个更实际的问题：你说的 loop 到底是什么？</p><p>我觉得这场争论真正有价值的地方，不在 prompt。</p><p>对高强度使用 AI 的人来说，prompt 早就不是主战场。过去一年，很多人的使用方式已经从 prompt 走到 context，再走到 harness。</p><p>我们不只是把问题写得更清楚。</p><p>我们开始给模型准备上下文包，固定项目规则，接入工具，开放文件系统，跑测试，用 MCP，写 skills，把不同 agent 放到 worktree 里隔离。</p><p>这已经不是聊天了。</p><p>这是在给 agent 搭工作环境。</p><p>所以这篇文章真正想讨论的不是&quot;prompt 死没死&quot;。这个问题有点旧。</p><p>更值得问的是：当我们已经有了一个 agent harness，下一层是什么？</p><p>我的判断是：</p><blockquote><p>Harness 让 agent 能干活。Loop 让 agent 的工作可以被持续调度、验证和积累。</p></blockquote><h2 id="prompt-→-context-→-harness-→-loop" tabindex="-1">Prompt → Context → Harness → Loop <a class="header-anchor" href="#prompt-→-context-→-harness-→-loop" aria-label="Permalink to &quot;Prompt → Context → Harness → Loop&quot;">​</a></h2><p>这四层最好分开。很多人把它们揉在一起，所以讨论会乱。</p><p>Prompt 阶段，我们靠表达能力赢。谁更会拆任务、写约束、追问、纠错，谁就更像高手。</p><p>Context 阶段，我们开始意识到模型每次乱猜，常常不是因为它笨，而是因为它缺背景。于是我们开始管理 repo、docs、examples、memory、constraints。</p><p>Harness 阶段，agent 开始接触真实环境。它能读文件，能改代码，能跑命令，能查 issue，能用 connector，能在隔离 worktree 里工作。这一层很重要——没有 harness，agent 只能在聊天框里给建议；有了 harness，它才真的能动手。</p><p>但 harness 通常解决的是单次执行质量。它问的是：</p><ul><li><p>agent 能不能拿到正确上下文？</p></li><li><p>agent 能不能调用需要的工具？</p></li><li><p>agent 能不能访问真实文件？</p></li><li><p>agent 能不能跑测试？</p></li><li><p>agent 能不能交付一个结果？</p></li></ul><p>这些问题解决完，你会得到一个很能干的 agent。</p><p>但连续工作的麻烦才刚开始：</p><ul><li><p>谁来发现任务？</p></li><li><p>谁来启动它？</p></li><li><p>谁判断结果能不能用？</p></li><li><p>失败写在哪里？</p></li><li><p>明天从哪里继续？</p></li><li><p>跑偏了怎么停？</p></li></ul><p>这些不是 harness 的核心问题。这是 loop 的问题。</p><h2 id="loop-是-harness-上面的一层" tabindex="-1">Loop 是 harness 上面的一层 <a class="header-anchor" href="#loop-是-harness-上面的一层" aria-label="Permalink to &quot;Loop 是 harness 上面的一层&quot;">​</a></h2><p>harness 是单个 agent 的运行环境。loop 在它上一层，负责触发、分派、检查、记录、恢复和停止。</p><p>如果 harness 是工作台，loop 就是工单系统、班次表和质检规则。</p><ul><li><p>工作台决定能不能干。</p></li><li><p>loop 决定什么时候干、谁来干、谁检查、干到哪里、明天怎么接。</p></li></ul><p>还有人讲得更直白：</p><blockquote><p>loop 是一个小程序，它提示 agent，读取输出，判断是否完成，没完成就继续，完成、失败或超预算就停。</p></blockquote><p>这和 cron 也不一样。cron 跑固定脚本。loop 每一轮都让模型读当前状态，再决定下一步。</p><p>可以说，loop 是 cron 加上一个运行时决策者。 有趣的工程不在&quot;它会定时跑&quot;，而在我们怎么约束这个决策者：给它什么状态，让它调用什么 skill，让谁验收，什么条件下必须停。</p><p>让我们把这个问题拆得更小一点：prompt 是单步棋，loop 是一套策略。</p><p>这句话比&quot;别写 prompt，去写 loop&quot;更准确。因为它没有否定 prompt，而是把 prompt 放回了正确位置：prompt 只是某一轮的动作，不是整盘棋的规则。</p><p>一个最小可用 loop，其实要同时有五个部件：</p><ul><li><p>done check：先用代码定义什么叫完成。</p></li><li><p>context builder：每一轮从当前 state 生成 prompt，而不是人手动喂。</p></li><li><p>act and capture：让 agent 执行，并捕获 diff、输出、错误和新状态。</p></li><li><p>feedback path：失败不是终点，失败要变成下一轮输入。</p></li><li><p>stop conditions：限制轮数、预算和风险动作，必要时拉人回来确认。</p></li></ul><p>这就把 loop 从一个抽象概念拉回到一个很具体的小控制器：</p><p>所以，loop 不是一个更长的 prompt。loop 是一个把 prompt、状态、执行、验证和停止条件接起来的控制结构。</p><h2 id="为什么loop-engineering会突然火" tabindex="-1">为什么Loop Engineering会突然火 <a class="header-anchor" href="#为什么loop-engineering会突然火" aria-label="Permalink to &quot;为什么Loop Engineering会突然火&quot;">​</a></h2><p>我不认为大家是突然爱上了 loop 这个词。</p><p>更合理的解释是：高强度 AI 用户集体撞到了同一个瓶颈。</p><p>单次 agent 能力已经很强。它能修 bug，能写文档，能生成代码，能读上下文，能调用工具，能处理多步骤任务。</p><p>但真实工作很少是一次性任务。真实工作更像这样：</p><p>这不是一个更长的 prompt 能解决的。这需要控制层。</p><p>那篇《The End of Software Engineering》论文提供了更底层的解释：</p><blockquote><p>传统软件把决策逻辑提前写进静态代码，agent 系统把一部分决策放到运行时，由模型、工具、记忆和规划一起完成。</p></blockquote><p>也就是说，我们不只是让 AI 更快地写软件。更深的变化是：软件行为本身开始 agent 化。</p><p>当决策越来越多发生在运行时，你需要设计的就不只是代码，也不是单个 agent。你要设计模型、工具、记忆、规划、状态和验证之间的执行结构。</p><p>这就是 harness 和 loop 重要起来的原因：</p><ul><li><p>agent 需要运行环境。</p></li><li><p>运行环境还需要控制系统。</p></li></ul><h2 id="让我们直面困难-怎么设计一个-loop" tabindex="-1">让我们直面困难：怎么设计一个 loop <a class="header-anchor" href="#让我们直面困难-怎么设计一个-loop" aria-label="Permalink to &quot;让我们直面困难：怎么设计一个 loop&quot;">​</a></h2><p>在了解了前面的情况后,面临的是一个更落地的问题：</p><blockquote><p>我现在已经有一个 agent，怎么把它放进一个会自己推进、会自己检查、会自己停止的循环里？</p></blockquote><p>设计 loop 时，第一步不是写 prompt，也不是加定时任务，而是先画出这六个接口。</p><ol><li><p>目标接口：这次 loop 到底要推进什么任务。</p></li><li><p>状态接口：每一轮开始时，它能读到哪些 state。</p></li><li><p>上下文接口：state 怎么被组装成这一轮 prompt。</p></li><li><p>执行接口：agent 能做哪些动作，能调用哪些工具。</p></li><li><p>结果接口：执行后必须捕获哪些输出。</p></li><li><p>停止接口：什么叫完成，什么叫失败，什么时候必须停。</p></li></ol><p>用一条修 bug 任务举例，loop 不是这样：</p><p>而是这样：</p><p>怎么把 loop 从“让 agent 自己干活”的口号，改成了一个可检查的控制结构?</p><p>很多人会把 loop 理解成“自动继续”。这个理解太薄。</p><p>真正的 loop 不是自动继续，而是有条件地继续。</p><ul><li><p>没有 done check，继续就是失控。</p></li><li><p>没有 capture，继续就是失忆。</p></li><li><p>没有 feedback，继续就是重复撞墙。</p></li><li><p>没有 state，继续就是重新开聊。</p></li><li><p>没有 stop condition，继续就是账单事故。</p></li></ul><p>继续延伸,把讨论从“AI 使用界面正在上移”，往前推到了“这个控制层到底怎么设计”。</p><p>这也让前面的四层路径更完整：</p><p>loop 的关键词不是自动化，而是闭环。</p><p>我们能不能定义完成，能不能捕获结果，能不能把失败变成下一轮输入，能不能在成本和风险失控前停止。这些问题答出来，才算真的开始设计 loop。</p><h2 id="skill-才是-loop-里的资产" tabindex="-1">Skill 才是 loop 里的资产 <a class="header-anchor" href="#skill-才是-loop-里的资产" aria-label="Permalink to &quot;Skill 才是 loop 里的资产&quot;">​</a></h2><p>这里有一个判断：</p><blockquote><p>loop 是 plumbing，skill 才是资产。</p></blockquote><p>这点很多人会忽略。</p><p>如果我们的 loop 只是每次把一大段 prompt 塞给 agent，让它重新理解项目、重新猜规则、重新摸索做法，那它只是一个很贵的 while true。</p><ul><li><p>每一轮都在重买上下文。</p></li><li><p>每一轮都在重付认知税。</p></li></ul><p>真正能复利的是 skill。skill 把项目规则、执行习惯、失败经验、检查方式写到外面，让 agent 每次运行都能读到同一套外部意图。</p><blockquote><p>没有 skill，loop 会反复冷启动。有 skill，loop 才有积累。</p></blockquote><p>日常实践：当我们发现自己一遍又一遍做同一个步骤，就把它抽出来做成 skill；当你解决了一个难问题，也把那个解法保存成 skill。</p><p>这里的关键不是&quot;给 agent 更多知识&quot;，而是把重复认知劳动从模型这一轮的上下文里拿出来，变成外部可调用的资产。</p><p>否则 loop 每跑一轮，模型都在重新理解项目、重新推导规则、重新摸索工具。它看起来在自动化，本质上是在反复交同一笔学费。</p><p>那么继续来解决下一个问题:怎么让 agent 不再依赖单次聊天上下文，而是进入一个能持续工作的外部系统?</p><p>这几块拼起来，loop 才不会只是一个定时 prompt。</p><h2 id="从-harness-到-loop-别跳步" tabindex="-1">从 harness 到 loop，别跳步 <a class="header-anchor" href="#从-harness-到-loop-别跳步" aria-label="Permalink to &quot;从 harness 到 loop，别跳步&quot;">​</a></h2><p>我不建议一上来就追复杂 loop。</p><p>很多人看到 loop，会立刻想到定时、并发、多 agent、自动开 PR、自动发消息。这个顺序很危险。</p><p>先有 harness，再有 loop。跳过 harness 直接 loop，容易得到一台定时制造混乱的机器。</p><p>更稳的改造路径：</p><ol><li><p>选一个你已经用 AI 做过 10 次以上的重复任务</p></li><li><p>先写完成条件，不写自动化</p></li><li><p>固定 context pack，让模型每次拿到同一组关键背景</p></li><li><p>把稳定做法沉淀成 skill</p></li><li><p>把 agent 放进已有 harness 里跑，确认它能访问工具、文件和测试</p></li><li><p>单独设计 checker，不让 maker 自己判自己完成</p></li><li><p>把结果、失败、下一步写进外部 state</p></li><li><p>最后才加 trigger：定时、事件、手动按钮，或 goal 条件</p></li><li><p>加预算上限、最大迭代次数、无进展检测和停止条件</p></li></ol><blockquote><p>trigger 应该最后加。</p></blockquote><p>很多人一上来想加 trigger，是因为 trigger 最有自动化的感觉。但真正让 loop 成立的，不是&quot;它会自动跑&quot;，而是前面几个更土的东西已经存在：</p><ul><li><p>有 is_done，知道什么时候停。</p></li><li><p>有 state，知道这一轮基于什么继续。</p></li><li><p>有 capture，知道上一轮到底发生了什么。</p></li><li><p>有 feedback，能把失败变成下一轮输入。</p></li><li><p>有 guardrail，能在成本、轮数或风险越界前刹车。</p></li></ul><p>这些东西没写清楚之前，trigger 越早出现，风险越大。</p><p>trigger 看起来最像自动化，也最容易让人兴奋。但一个没有完成条件、没有 checker、没有 external state 的 trigger，只是把不可靠的单次执行改成不可靠的定期执行。</p><h2 id="loop-的风险比-prompt-更隐蔽" tabindex="-1">Loop 的风险比 prompt 更隐蔽 <a class="header-anchor" href="#loop-的风险比-prompt-更隐蔽" aria-label="Permalink to &quot;Loop 的风险比 prompt 更隐蔽&quot;">​</a></h2><p>prompt 写坏了，通常一眼能看出来。</p><p>loop 设计坏了，可能会连续几天产出看起来很完整的垃圾：</p><ul><li><p>它可能不停重试。</p></li><li><p>它可能每一轮都把 context 塞得更大，最后噪音压过信号。</p></li><li><p>它可能把第一轮的小错误带到第三轮、第五轮、第十轮。</p></li><li><p>它可能让 checker 变成摆设。</p></li><li><p>它也可能让人产生一种危险的舒服感：系统在跑，我就不用看了。</p></li></ul><p>这才是最危险的部分。</p><blockquote><p>loop 不会删除人。它只是把人的判断放到更高的位置。</p></blockquote><p>论文里也有类似冷水：agent 在孤立任务上能力很强，但放到连续软件演化里，错误会传播，表现会明显掉下去。</p><p>这个结论放到所有长期 AI 工作流里都成立：单次成功，不等于连续可靠。</p><p>所以，高强度 AI 用户接下来要学的，不是怎么把人完全拿掉。而是怎么设计验证、状态、预算和停止条件。</p><p>虽然那个论文说代码以死,但是我觉得：写代码很便宜，让一个 loop 一遍又一遍地写代码并不便宜。</p><p>这句话应该贴在所有 unattended agent 设计前面。</p><p>因为 loop 的成本不是单次生成成本，而是每一轮推理、工具调用、测试、失败、重试累积出来的成本。一个没有停止条件的 loop，不只是一个工程 bug，还是一张会在你睡觉时继续变大的账单。</p><p>所以，真正成熟的 loop 设计，必须把&quot;会不会成功&quot;和&quot;失败时怎么停&quot;放在同一优先级。只谈自主，不谈停机，本质上还是 demo 思维。</p><h2 id="真正的分水岭" tabindex="-1">真正的分水岭 <a class="header-anchor" href="#真正的分水岭" aria-label="Permalink to &quot;真正的分水岭&quot;">​</a></h2><p>我现在会用一个问题判断某个人是不是进入下一层 AI 使用：</p><blockquote><p>他是不是还在展示&quot;我让 AI 做了什么&quot;。</p></blockquote><blockquote></blockquote><blockquote><p>还是已经开始描述&quot;我设计了一套什么系统，让 AI 持续做什么，并且我怎么知道它没跑偏&quot;。</p></blockquote><p>前者是 agent demo。后者才是 loop thinking。</p><p>高阶 AI 使用的路径，不是 prompt 到 agent 这么简单。更准确地说：</p><p>下一阶段真正拉开差距的，不是谁有更长的 prompt，也不是谁堆了更多上下文。</p><p>而是谁能把自己的 harness，变成一个有节奏、有状态、有验证、有停止条件的 loop。</p><p>这也是这几篇海外文章同时火起来的原因。</p><p>它们讨论的不是一个新命令。</p><p>它们讨论的是 AI 使用界面的下一次上移。</p><p>祝大家都能早日熟练掌握Loop Engineering!</p><h2 id="资料来源" tabindex="-1">资料来源 <a class="header-anchor" href="#资料来源" aria-label="Permalink to &quot;资料来源&quot;">​</a></h2><p>本文基于以下四份资料提炼，不是逐篇摘要：</p><ul><li><p>Zhenfeng Cao, “The End of Software Engineering: How AI Agents Are Fundamentally Restructuring the Software Paradigm”, arXiv 2606.05608v1</p></li><li><p>Matt Van Horn, “WTF Is a Loop? Peter Steinberger vs. Boris Cherny”</p></li><li><p>Addy Osmani, “Loop Engineering.”</p></li><li><p>Amit Shekhar, “How to design a loop that prompts your agent?”</p></li></ul>',141)])])}const g=o(a,[["render",i]]);export{c as __pageData,g as default};
